def parse_port(value):
    if isinstance(value, bool):
        raise ValueError('invalid port')
    if isinstance(value, int):
        port = value
    elif isinstance(value, str) and value.isdecimal():
        port = int(value)
    else:
        raise ValueError('invalid port')
    if not 1 <= port <= 65535:
        raise ValueError('invalid port')
    return port
